def add_tag(tag, tags=None):
    if tags is None:
        tags = []
    tags.append(tag)
    return tags

def shipping_cost(weight, express=False, country="UK"):
    cost = 3.5 if country == "UK" else 9.0
    cost += 0.5 * weight
    if express:
        cost *= 2
    return round(cost, 2)

